def _classify_legacy_records() -> None:
    """Classify existing rows from actual seed provenance; everything else stays 'unknown' until reviewed.

    The demo seeder records `world_version` in organizations.settings. Only those organizations (and rows
    inside them) become 'demo'. No existing row is ever classified 'operational' by this migration.
    """
    op.execute("""
        UPDATE organizations SET data_class = 'demo'
        WHERE (settings::jsonb ? 'world_version')
    """)
    for table in (
        "tickets",
        "ticket_messages",
        "knowledge_documents",
        "investigation_runs",
        "proposals",
        "action_ledger",
        "artifacts",
    ):
        op.execute(f"""
            UPDATE {table} t SET data_class = o.data_class
            FROM organizations o WHERE o.id = t.organization_id AND o.data_class <> 'unknown'
        """)
    # Source channel is inferable only where the record itself shows it.
    op.execute("""
        UPDATE tickets t SET source_kind = 'seed'
        WHERE t.created_by_user_id IS NULL AND (t.external_event_id LIKE 'seed-%' OR t.external_event_id LIKE 'hist-%')
    """)
    op.execute("""
        UPDATE tickets t SET source_kind = CASE WHEN m.role = 'customer' THEN 'portal' ELSE 'manual' END
        FROM memberships m
        WHERE t.created_by_user_id = m.user_id AND m.organization_id = t.organization_id AND t.source_kind = 'unknown'
    """)
    op.execute("UPDATE tickets SET received_at = created_at WHERE received_at IS NULL")
    op.execute("""
        UPDATE ticket_messages tm SET source_kind = t.source_kind
        FROM tickets t WHERE t.id = tm.ticket_id AND tm.author_kind = 'customer'
    """)
    op.execute("""
        UPDATE ticket_messages SET source_kind = 'manual' WHERE author_kind <> 'customer' AND source_kind = 'unknown'
    """)
    op.execute("""
        UPDATE knowledge_documents d SET source_kind = 'seed'
        FROM document_versions v
        WHERE v.document_id = d.id AND v.source_filename LIKE 'data/%'
    """)


